#ifndef PACK_H
#define PACK_H

#include <string>

struct PackMember {
    std::string name;
    std::string role; // Hunter, Scout, Guard
    int loyalty; // 0-100
    PackMember* next;
};

class Pack {
private:
    PackMember* head;
    int size;
public:
    Pack();
    ~Pack();
    void addMember(std::string name, std::string role, int loyalty);
    void displayPack();
    int getSize();
    bool removeMember(std::string name); // If loyalty low
    PackMember* getHead(); // Add method to access pack members
};

#endif

#include "../include/pack.h"
#include <iostream>

Pack::Pack() : head(nullptr), size(0) {}

Pack::~Pack() {
    PackMember* current = head;
    while (current) {
        PackMember* next = current->next;
        delete current;
        current = next;
    }
}

void Pack::addMember(std::string name, std::string role, int loyalty) {
    if (size >= 5) {
        std::cout << "Pack is full (max 5 members)." << std::endl;
        return;
    }
    PackMember* newMember = new PackMember{name, role, loyalty, nullptr};
    if (!head) {
        head = newMember;
    } else {
        PackMember* current = head;
        while (current->next) current = current->next;
        current->next = newMember;
    }
    size++;
    std::cout << "Recruited " << name << " as " << role << "." << std::endl;
}

void Pack::displayPack() {
    if (size == 0) {
        std::cout << "No pack members." << std::endl;
        return;
    }
    PackMember* current = head;
    std::cout << "Pack Members:" << std::endl;
    while (current) {
        std::cout << "- " << current->name << " (" << current->role << ", Loyalty: " << current->loyalty << ")" << std::endl;
        current = current->next;
    }
}

int Pack::getSize() {
    return size;
}

PackMember* Pack::getHead() {
    return head;
}

bool Pack::removeMember(std::string name) {
    PackMember* current = head;
    PackMember* prev = nullptr;
    while (current) {
        if (current->name == name) {
            if (prev) prev->next = current->next;
            else head = current->next;
            delete current;
            size--;
            return true;
        }
        prev = current;
        current = current->next;
    }
    return false;
}

#ifndef ACTION_QUEUE_H
#define ACTION_QUEUE_H

#include <queue>
#include <string>
#include <functional>

struct Wolf; // Forward declaration

struct Action {
    std::string description;
    void (*execute)(void*);  // Function to execute on Wolf object
};

class ActionQueue {
private:
    std::queue<Action> actions;
public:
    ActionQueue();
    void enqueue(Action a);
    void processNext(Wolf& wolf);
    bool isEmpty();
};

#endif

#include "../include/action_queue.h"
#include <iostream>

ActionQueue::ActionQueue() {}

void ActionQueue::enqueue(Action a) {
    actions.push(a);
}

void ActionQueue::processNext(Wolf& wolf) {
    if (!actions.empty()) {
        Action a = actions.front();
        actions.pop();
        std::cout << "\033[34m" << a.description << "\033[0m" << std::endl;
        a.execute(&wolf);
    }
}

bool ActionQueue::isEmpty() {
    return actions.empty();
}

