void GameWindow::onInventory() {
    // Display inventory contents
    QString inventoryText = "Inventory:\n";

    Item* current = inventory.getHead();
    if (current) {
        int itemCount = 0;
        while (current) {
            inventoryText += QString("- %1 (x%2)\n").arg(QString::fromStdString(current->name)).arg(current->quantity);
            current = current->next;
            itemCount++;
        }
        inventoryText += QString("\nTotal items: %1").arg(itemCount);
    } else {
        inventoryText += "No items in inventory.";
    }

    QMessageBox::information(this, "Inventory", inventoryText);
}

void GameWindow::onPack() {
    // Display pack members
    QString packText = "Pack Members:\n";

    PackMember* current = pack.getHead(); // Assuming there's a getHead() method, or we'll need to modify Pack class
    if (current) {
        int memberCount = 0;
        while (current) {
            packText += QString("- %1 (%2, Loyalty: %3)\n")
                           .arg(QString::fromStdString(current->name))
                           .arg(QString::fromStdString(current->role))
                           .arg(current->loyalty);
            current = current->next;
            memberCount++;
        }
        packText += QString("\nTotal members: %1").arg(memberCount);
    } else {
        packText += "No pack members.";
    }

    QMessageBox::information(this, "Pack", packText);
}

void GameWindow::updateStats() {
    // Update stats display
    QString statsText = QString("Health: %1 | Hunger: %2 | Energy: %3 | Spirit: %4")
                        .arg(wolf.health).arg(wolf.hunger).arg(wolf.energy).arg(wolf.spirit);
    statsLabel->setText(statsText);

    // Update stat bars
    healthBar->animateTo(wolf.health);
    hungerBar->animateTo(100 - wolf.hunger); // Invert for hunger (lower is better)
    energyBar->animateTo(wolf.energy);
    spiritBar->animateTo(wolf.spirit);

    // Check for game over condition
    if (wolf.health <= 0) {
        QMessageBox::critical(this, "Game Over", "Your wolf has died! Game Over.");
        QTimer::singleShot(0, this, &QWidget::close); // Close the window after showing the message
    }

    // Check for events
    checkEvents();
}

void GameWindow::updateDisplay() {
    DecisionNode* current = tree.getCurrentNode();
    if (current) {
        storyLabel->setText(QString::fromStdString(current->description));

        // Update wolf graphic based on scenario
        updateWolfGraphic(current->scenarioID);

        if (current->isEnding) {
            buttonA->setEnabled(false);
            buttonB->setEnabled(false);
            buttonA->setText("Choice A");
            buttonB->setText("Choice B");
            storyLabel->setText(storyLabel->text() + "\n\n" + QString::fromStdString(current->endingText));
        } else {
            buttonA->setText(QString::fromStdString("A: " + current->choiceA_text));
            buttonB->setText(QString::fromStdString("B: " + current->choiceB_text));
            buttonA->setEnabled(true);
            buttonB->setEnabled(true);
        }
    }
}

void GameWindow::updateWolfGraphic(int scenarioId) {
    // Change the wolf graphic based on the scenario
    QString graphicText = "Wolf";

    // Add scenario-specific graphics
    switch(scenarioId) {
        case 1:
            graphicText = "🌲\n🐺 Wolf\nForest";
            break;
        case 2:
            graphicText = "🦌\n🐺 Wolf\nHunting";
            break;
        case 3:
            graphicText = "🐻\n🐺 Wolf\nBear";
            break;
        case 4:
            graphicText = "🐰\n🐺 Wolf\nRabbit";
            break;
        case 5:
            graphicText = "🌳\n🐺 Wolf\nResting";
            break;
        default:
            graphicText = "🐺\nWolf\nAdventure";
            break;
    }

    wolfGraphic->setText(graphicText);

    // Change background color based on wolf's health with improved colors
    QString bgColor = "#8FBC8F"; // Default forest green
    if (wolf.health < 30) {
        bgColor = "#B22222"; // Firebrick red for low health
    } else if (wolf.health < 60) {
        bgColor = "#DAA520"; // Goldenrod yellow for medium health
    }

    wolfGraphic->setStyleSheet(QString("background-color: %1; border: 2px solid #556B2F; border-radius: 10px; color: white; font-weight: bold; font-size: 16px;").arg(bgColor));
}

void GameWindow::processChoice(bool isA) {
    DecisionNode* current = tree.getCurrentNode();
    if (current) {
        // Check if this is already an ending node
        if (current->isEnding) {
            return; // Don't allow choices on ending nodes
        }

        // Push current state before choice
        // history.push({current, wolf.health, wolf.hunger, wolf.energy});

        DecisionNode* nextNode = nullptr;
        if (isA) {
            nextNode = current->left;
        } else {
            nextNode = current->right;
        }

        // Only proceed if there's a valid next node
        if (nextNode) {
            tree.setCurrentNode(nextNode);
            updateDisplay();
        } else {
            // If there's no next node, this might be an ending scenario
            QMessageBox::information(this, "Game", "No further options available.");
        }
    }
}

void GameWindow::checkEvents() {
    // Check for random events
    if (dis(gen) < 0.1) { // 10% chance of event (less frequent)
        if (!events.isEmpty()) {
            Event e = events.extractMin();
            std::string msg = e.name + ": " + e.description;

            // Instead of a popup, update the story label with event info
            QString currentText = storyLabel->text();
            storyLabel->setText(currentText + "\n\n[EVENT] " + QString::fromStdString(msg));

            // Apply the event effect to the wolf
            e.effect(&wolf);

            // Put the event back in the queue with reset priority
            events.insert(e);
        }
    }
}
